      await writeFile(join(directory, "partition.json"), JSON.stringify({ sourceSha: env.EVAL_SOURCE_SHA, shard, cases: selected }));
      command = [...base, ...args.filter(arg => !arg.startsWith("--shard=")), `--test-list=${listPath}`];
